{
  "name": "MediGuide AI - Symptom Analyzer",
  "description": "An AI-powered health assistant that analyzes symptoms and medical images to provide preliminary insights and educational information. Not a replacement for professional medical advice."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Message {
  id: string;
  role: 'user' | 'model';
  content: string;
  timestamp: number;
  attachments?: string[]; // Base64 strings
}

export interface AnalysisState {
  isLoading: boolean;
  error: string | null;
  conversation: Message[];
}

export enum UrgencyLevel {
  LOW = 'Low',
  MODERATE = 'Moderate',
  HIGH = 'High',
  EMERGENCY = 'Emergency'
}

export interface HealthProfile {
  age?: string;
  gender?: string;
  preExistingConditions?: string;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Message } from "../types";

// Initialize the client
// API Key is guaranteed to be in process.env.API_KEY per instructions
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
You are MediGuide AI, an advanced medical assistant designed to analyze symptoms and visual medical data (like skin conditions).
Your goal is to provide preliminary analysis, potential differential diagnoses, and advice on next steps.

CRITICAL RULES:
1. DISCLAIMER: You MUST always start or end your response with a brief reminder that you are an AI and this is NOT professional medical advice.
2. TONE: Be empathetic, professional, clear, and calm.
3. STRUCTURE: Use Markdown. Break down complex information into bullet points.
   - Potential Causes: List 3-5 possibilities from most likely to least likely.
   - Urgency Assessment: Clearly state if this sounds like something that needs immediate ER attention, a doctor's visit soon, or self-care.
   - Recommendations: Self-care tips (if applicable) and what specialist to see.
4. IMAGES: If an image is provided, analyze it visually. Describe what you see (color, texture, shape) before giving a diagnosis.
5. SAFETY: If the symptoms sound life-threatening (e.g., chest pain, difficulty breathing, stroke symptoms, severe bleeding), urge the user to call emergency services immediately.

Use the model 'gemini-3-pro-preview' for complex reasoning.
`;

export const sendMessageToGemini = async (
  history: Message[],
  newMessage: string,
  images: string[] = [] // Array of base64 strings
): Promise<string> => {
  try {
    // Construct the prompt. 
    // We send the conversation history as context if needed, but for the simplest implementation 
    // of a "Predictor", we often just need the current context + previous turn.
    // However, to keep it stateless and robust, we'll format the history into a chat format
    // or just send the current request if it's a fresh analysis.

    // For this specific app pattern (Assessment), we want to maintain chat history 
    // so the user can answer follow-up questions.

    const contents: any[] = [];

    // Add history (excluding the current new message which we'll add at the end)
    // We limit history to last 10 messages to prevent token overflow, though Gemini window is large.
    const recentHistory = history.slice(-10);

    // We need to format history for the API if we were using `sendMessage` on a chat object, 
    // but here we are using `generateContent` statelessly for maximum control or we can use `chats.create`.
    // Let's use `chats.create` for easier history management.

    const chat = ai.chats.create({
      model: 'gemini-3-pro-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        thinkingConfig: { thinkingBudget: 1024 }, // Enable some thinking for medical reasoning
      },
      history: recentHistory.map(msg => ({
        role: msg.role,
        parts: [{ text: msg.content }],
      })),
    });

    // Prepare the new message content
    let messageContent: any = { role: 'user', parts: [] };

    // Add text
    messageContent.parts.push({ text: newMessage });

    // Add images if any
    if (images.length > 0) {
      images.forEach(base64Data => {
        // Strip the data:image/png;base64, prefix if present
        const cleanBase64 = base64Data.split(',')[1] || base64Data;
        const mimeType = base64Data.match(/data:([a-zA-Z0-9]+\/[a-zA-Z0-9-.+]+).*,.*/)?.[1] || 'image/jpeg';

        messageContent.parts.push({
          inlineData: {
            mimeType: mimeType,
            data: cleanBase64
          }
        });
      });
    }

    // Since chat.sendMessage only accepts a string message or a simpler structure in the SDK signature usually,
    // strict adherence to the new SDK: `chat.sendMessage` takes `{ message: ... }`.
    // The `message` property can be a string or a Part array or a Content object.

    // IMPORTANT: The instructions say `chat.sendMessage` only accepts the `message` parameter.
    // And for `generateContent` it accepts `contents`.
    // If we have images, `chat.sendMessage` might handle it if we pass the right structure, 
    // but to be safe and strictly follow the "Generative Content" guidance for multimodal:

    // Let's stick to `ai.models.generateContent` if we have images + history manually, 
    // OR use `chat.sendMessage` if it supports parts. 
    // The SDK definition usually allows `message` to be `string | Array<Part>`.

    // Let's try to construct the payload for `chat.sendMessage`.
    // If `images` are present, we construct a multipart message.

    const messagePayload = images.length > 0 
      ? messageContent.parts // Pass array of parts
      : newMessage; // Pass string

    const response: GenerateContentResponse = await chat.sendMessage({
      message: messagePayload
    });

    return response.text || "I apologize, but I couldn't generate a response. Please try again.";

  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw new Error("Failed to analyze symptoms. Please check your connection and try again.");
  }
};

