import React, { useState, useRef, ChangeEvent } from 'react';
import { Send, Image as ImageIcon, X, Paperclip } from 'lucide-react';

interface InputAreaProps {
  onSendMessage: (text: string, images: string[]) => void;
  isLoading: boolean;
}

const InputArea: React.FC<InputAreaProps> = ({ onSendMessage, isLoading }) => {
  const [text, setText] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSend = () => {
    if ((!text.trim() && images.length === 0) || isLoading) return;
    onSendMessage(text, images);
    setText('');
    setImages([]);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      files.forEach(file => {
        const reader = new FileReader();
        reader.onloadend = () => {
          setImages(prev => [...prev, reader.result as string]);
        };
        reader.readAsDataURL(file);
      });
    }
    // Reset file input
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const removeImage = (index: number) => {
    setImages(prev => prev.filter((_, i) => i !== index));
  };

  return (
    <div className="bg-white border-t border-slate-200 p-4 sticky bottom-0 z-10 w-full max-w-4xl mx-auto shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">

      {/* Image Preview Area */}
      {images.length > 0 && (
        <div className="flex gap-3 mb-3 overflow-x-auto pb-2 scrollbar-hide">
          {images.map((img, idx) => (
            <div key={idx} className="relative group flex-shrink-0">
              <img src={img} alt="Preview" className="h-20 w-20 object-cover rounded-lg border border-slate-200" />
              <button 
                onClick={() => removeImage(idx)}
                className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 shadow-md hover:bg-red-600 transition-colors"
              >
                <X size={12} />
              </button>
            </div>
          ))}
        </div>
      )}

      <div className="flex items-end gap-2 bg-slate-50 border border-slate-200 rounded-2xl p-2 focus-within:ring-2 focus-within:ring-teal-500 focus-within:border-transparent transition-all">
        <button 
          onClick={() => fileInputRef.current?.click()}
          className="p-3 text-slate-400 hover:text-teal-600 hover:bg-teal-50 rounded-xl transition-colors"
          title="Upload image"
          disabled={isLoading}
        >
          <ImageIcon size={22} />
        </button>
        <input 
          type="file" 
          ref={fileInputRef} 
          onChange={handleFileChange} 
          className="hidden" 
          accept="image/*" 
          multiple 
        />

        <textarea
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Describe symptoms (e.g., 'I have a red rash on my arm that itches...')"
          className="flex-1 bg-transparent border-none resize-none focus:ring-0 text-slate-800 placeholder-slate-400 py-3 max-h-32 min-h-[48px]"
          rows={1}
          disabled={isLoading}
        />

        <button 
          onClick={handleSend}
          disabled={(!text.trim() && images.length === 0) || isLoading}
          className={`p-3 rounded-xl flex items-center justify-center transition-all ${
            (!text.trim() && images.length === 0) || isLoading
              ? 'bg-slate-200 text-slate-400 cursor-not-allowed'
              : 'bg-teal-600 text-white hover:bg-teal-700 shadow-md hover:shadow-lg active:scale-95'
          }`}
        >
          {isLoading ? (
            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
          ) : (
            <Send size={20} />
          )}
        </button>
      </div>
      <p className="text-center text-xs text-slate-400 mt-2">
        AI can make mistakes. Consider checking important information.
      </p>
    </div>
  );
};

export default InputArea;

import React, { useState, useEffect, useRef } from 'react';
import { Activity, ShieldCheck, Info } from 'lucide-react';
import DisclaimerModal from './components/DisclaimerModal';
import MessageBubble from './components/MessageBubble';
import InputArea from './components/InputArea';
import { Message } from './types';
import { sendMessageToGemini } from './services/geminiService';

const App: React.FC = () => {
  const [hasAcceptedDisclaimer, setHasAcceptedDisclaimer] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleAcceptDisclaimer = () => {
    setHasAcceptedDisclaimer(true);
    // Add initial greeting
    setMessages([
      {
        id: 'init-1',
        role: 'model',
        content: "# Welcome to MediGuide AI \n\nI'm here to help you understand your symptoms. You can describe how you're feeling or upload a photo of any visible conditions (like a rash).\n\n**Please note:** I am an AI, not a doctor. In emergencies, call your local emergency number.",
        timestamp: Date.now()
      }
    ]);
  };

  const handleSendMessage = async (text: string, images: string[]) => {
    // 1. Add user message to UI
    const userMsgId = Date.now().toString();
    const userMessage: Message = {
      id: userMsgId,
      role: 'user',
      content: text,
      timestamp: Date.now(),
      attachments: images
    };

    setMessages(prev => [...prev, userMessage]);
    setIsLoading(true);

    try {
      // 2. Call Gemini Service
      const responseText = await sendMessageToGemini(messages, text, images);

      // 3. Add model response to UI
      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: responseText,
        timestamp: Date.now()
      };

      setMessages(prev => [...prev, modelMessage]);
    } catch (error) {
      console.error(error);
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: "I'm having trouble connecting to the service right now. Please try again in a moment.",
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 font-sans">
      {!hasAcceptedDisclaimer && <DisclaimerModal onAccept={handleAcceptDisclaimer} />}

      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-20 shadow-sm">
        <div className="max-w-4xl mx-auto px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-teal-600 p-2 rounded-lg text-white">
              <Activity size={24} />
            </div>
            <div>
              <h1 className="text-xl font-bold text-slate-800 tracking-tight">MediGuide AI</h1>
              <p className="text-xs text-teal-600 font-medium">Symptom & Visual Analysis</p>
            </div>
          </div>
          <div className="hidden md:flex items-center gap-4 text-sm text-slate-500">
            <div className="flex items-center gap-1">
              <ShieldCheck size={16} className="text-teal-600" />
              <span>Private & Secure</span>
            </div>
            <div className="flex items-center gap-1">
              <Info size={16} className="text-teal-600" />
              <span>For Educational Use Only</span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Chat Area */}
      <main className="flex-1 overflow-y-auto p-4 md:p-6 scroll-smooth">
        <div className="max-w-4xl mx-auto space-y-2">
          {messages.map((msg) => (
            <MessageBubble key={msg.id} message={msg} />
          ))}
          {/* Invisible element to scroll to */}
          <div ref={messagesEndRef} />
        </div>
      </main>

      {/* Input Area */}
      <InputArea onSendMessage={handleSendMessage} isLoading={isLoading} />
    </div>
  );
};

export default App;

